<script setup lang="ts">
import {ref, onMounted, onBeforeUnmount, nextTick, watch} from 'vue'
import {useDisplay} from "vuetify/framework"
//@ts-ignore
import {Swiper, SwiperSlide} from 'swiper/vue'
//@ts-ignore
import {Autoplay, EffectCoverflow, EffectCreative, EffectFade, EffectFlip} from 'swiper/modules'

// Swiper CSS
import 'swiper/css'
import 'swiper/css/pagination'
import 'swiper/css/navigation'
import 'swiper/css'
import 'swiper/css/effect-fade'
import type {Row} from "../../../types/EditorTypes"
import Render from "../Render.vue"

const {
  height = '200px',
  slidesData,
  radius = '16px',
  effect = 'slide',
  mode = 'each-slide-content',
  hoverEffect = 'no-effect',
  delay = 3500,
  locale
} = defineProps<{
  locale: string,
  effect?: 'slide' | 'fade' | 'coverflow' | 'flip',
  height?: string,
  mode?: 'single-content' | 'each-slide-content',
  radius?: string,
  hoverEffect?: 'no-effect' | 'zoom',
  delay: number,
  slidesData: {
    image: File | string,
    imageMobile: File | string,
    content: Row[],
    contentMobile: Row[],
    gradColor1?: string,
    gradColor2?: string,
    gradColor3?: string,
  }[]
}>()

const config = useRuntimeConfig()
const {mdAndUp} = useDisplay()
const currentIndex = ref(0)
const dynamicHeight = ref(height)

// --- Logic functions ---

const onSlideChange = (swiper: any) => {
  currentIndex.value = swiper.realIndex
}

function reveal() {
  // Guard: Never run on Server Side
  if (process.server) return

  const reveals = document.querySelectorAll<HTMLElement>('.reveal')
  const windowHeight = window.innerHeight

  reveals.forEach(el => {
    const elementTop = el.getBoundingClientRect().top
    if (elementTop < windowHeight) {
      el.classList.add('active')
    } else {
      el.classList.remove('active')
    }
  })
}

function applyHeights() {
  if (process.server) return

  // Find heights based on the slide class rather than ID to avoid Loop-clone issues
  let maxContentHeight = 0
  slidesData.forEach((_, i) => {
    const el = document.getElementById(`slide${i}`)
    if (el && el.offsetHeight > maxContentHeight) {
      maxContentHeight = el.offsetHeight
    }
  })

  dynamicHeight.value = height
}

// --- Lifecycle & Watchers ---

// Instead of calling reveal() in the template, we watch the slide change
watch(currentIndex, () => {
  nextTick(() => {
    reveal()
  })
})

onMounted(async () => {
  await nextTick()

  // Initial check
  applyHeights()
  reveal()

  window.addEventListener('resize', applyHeights)
})

onBeforeUnmount(() => {
  if (!process.server) {
    window.removeEventListener('resize', applyHeights)
  }
})
</script>

<template>
  <div id="height-according-container" :style="{ height: dynamicHeight }"></div>

  <div
      class="fullpage-slider"
      id="slider-container"
      :style="{ height: dynamicHeight, borderRadius: radius, direction: 'ltr' }"
  >
    <div
        v-if="!!slidesData[0] && mode === 'single-content'"
        class="slider-overlay"
    >
      <Render
          :rows="mdAndUp
        ? slidesData[0].content
        : (slidesData[0].contentMobile.length !== 0
            ? slidesData[0].contentMobile
            : slidesData[0].content)"
          margin-top="0px"
          :locale="locale"
      />
    </div>
    <swiper
        @slideChange="onSlideChange"
        :style="{ width: '100%', height: dynamicHeight }"
        id="slider-container-swiper"
        :modules="[Autoplay, effect === 'coverflow' ? EffectCoverflow : (effect === 'fade' ? EffectFade : effect === 'flip' ? EffectFlip : EffectCreative)]"
        :loop="true"
        :effect="effect"
        :autoplay="{
        delay: delay,
        disableOnInteraction: false
      }"
    >
      <swiper-slide v-for="(slide, index) in slidesData" :key="index">
        <div
            v-if="slide.image"
            :class="`slide ${hoverEffect}`"
            :id="`slide${index}`"
            :style="{
            height: dynamicHeight,
            padding: '16px'
          }"
        >
          <picture style="position: absolute; left: 0; top: 0; width: 100%; height: 100%;">
            <source
                media="(max-width: 960px)"
                :srcset="config.public.baseUrl + '/' + (slide.imageMobile || slide.image)"
            >

            <img
                :src="config.public.baseUrl + '/' + slide.image"
                style="object-fit: cover; width: 100%; height: 100%;"
                alt="Codentral"
            >
          </picture>
          <div
              class="overlay"
              :style="{
      background: `linear-gradient(${slide.gradColor1}, ${slide.gradColor2}, ${slide.gradColor3})`
    }"
          />
          <Render
              v-if="currentIndex === index && mode!=='single-content'"
              :rows="mdAndUp ? slide.content : (slide.contentMobile.length !== 0 ? slide.contentMobile : slide.content)"
              margin-top="0px"
              :locale="locale"
          />
        </div>
      </swiper-slide>
    </swiper>
  </div>
</template>

<style scoped>
.fullpage-slider {
  position: absolute;
  width: 100%;
  overflow: hidden;
  top: 0;
}

/* Ensure the slides have a transition for the reveal effect */
:deep(.reveal) {
  opacity: 0;
}

:deep(.reveal.active) {
  opacity: 1;
}

.slide-container {
  background-size: cover;
  background-position: center;
  padding: 16px;
}

.overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.zoom img {
  transition: transform 500ms ease-in-out;
}

.zoom:hover img {
  transform: scale(1.1);
}

.zoom .overlay {
  transition: opacity 1s ease-in-out;
}

.zoom:hover .overlay {
  opacity: 0;
}

.slider-overlay {
  position: absolute;
  inset: 0;
  z-index: 10;

  /* optional */
  display: flex;
  align-items: center;
  justify-content: center;

  pointer-events: none; /* important if slides are clickable */
}

</style>